// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 newVal, uint256 oldVal) public {
        newVal = bound(newVal, 1, type(uint256).max);
        oldVal = bound(oldVal, 1, type(uint256).max);
        vm.assume(oldVal != newVal);
        // finalize initialization so SetMinSum must reject all further changes
        c.Initialized();
        // first (rejected) call establishes the revert path in both versions
        vm.prank(address(1));
        try c.SetMinSum(oldVal) { revert("should have reverted"); } catch {}
        // a second rejected call must NOT change MinSum
        vm.prank(address(2));
        bool ok;
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }
        // Rule: a reverted SetMinSum never changes MinSum.
        assertTrue(!ok && c.MinSum() == 0, "MinSum must be unchanged after a reverted SetMinSum");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v, bool doInit) public {
        // keep v wide: whole uint256 range is admissible
        if (doInit) {
            c.Initialized();
        }
        uint256 before = c.MinSum();
        vm.prank(address(this));
        bool ok;
        try c.SetMinSum(v) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a SetMinSum call that reverts must have NO effect on
        // MinSum; only a successful call may set it, and then to exactly v.
        assertTrue(
            ok ? (c.MinSum() == v && before == c.MinSum()) : (c.MinSum() == before),
            "reverting SetMinSum must not change MinSum; success must set it to v"
        );
    }
}

