pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v, bool init) public {
        v = bound(v, 0, type(uint128).max);
        address actor = address(0xABCD);
        bool ok;
        if (init) {
            vm.prank(actor);
            c.Initialized();
        }
        vm.prank(actor);
        try c.SetMinSum(v) { ok = true; } catch { ok = false; }
        // Reference rule: SetMinSum(v) sets MinSum to v ONLY when it succeeds;
        // a reverting SetMinSum (because the contract was Initialized) leaves MinSum
        // unchanged. The mutant writes MinSum before the revert check, so an
        // initialized contract ends with MinSum == v even though the call reverted.
        assertTrue(ok == !init && c.MinSum() == (ok ? v : 0));
    }
}

