pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialVal, uint256 newVal, bool doInit) public {
        address actor = address(0xA11CE);

        // Establish a possibly-nonzero prior MinSum via a successful call.
        vm.prank(actor);
        c.SetMinSum(initialVal);
        uint256 prior = c.MinSum();
        assertTrue(prior == initialVal);

        // Optionally initialize the contract, so the second SetMinSum reverts.
        if (doInit) {
            vm.prank(actor);
            c.Initialized();
        }

        bool ok;
        vm.prank(actor);
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }

        // General rule: MinSum equals newVal exactly when the call succeeded;
        // a reverting SetMinSum must leave MinSum at its prior value.
        assertTrue(ok ? c.MinSum() == newVal : c.MinSum() == prior);
    }
}

