pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 v0, uint256 v1, address actor) public {
        // keep the domain wide: any values, any non-contract actor
        vm.assume(actor != address(0));

        // 1) a successful SetMinSum(v0) on the fresh (uninitialized) contract sets MinSum = v0
        vm.prank(actor);
        (bool ok0, ) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, v0));
        assertTrue(ok0);
        assertEq(c.MinSum(), v0);

        // 2) initialize the contract: from now on every SetMinSum must revert
        vm.prank(actor);
        c.Initialized();

        // 3) a reverting SetMinSum(v1) must NOT change MinSum: it stays v0.
        //    The mutant writes MinSum = v1 BEFORE the revert check, so it breaks the
        //    success/revert-to-state correspondence whenever v1 != v0.
        vm.prank(actor);
        (bool ok1, ) = address(c).call(abi.encodeWithSelector(c.SetMinSum.selector, v1));

        // single assertion (the earlier checks are plain observations of the setup):
        assertTrue(
            (ok1 && c.MinSum() == v1) || (!ok1 && c.MinSum() == v0),
            "MinSum must equal v only when SetMinSum succeeded; a reverting call must leave the old value"
        );
    }
}

