pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 firstVal, uint256 secondVal, address actor) public {
        vm.assume(actor != address(0));
        vm.startPrank(actor);
        bool ok1;
        try c.SetMinSum(firstVal) { ok1 = true; } catch { ok1 = false; }
        bool ok2;
        try c.SetMinSum(secondVal) { ok2 = true; } catch { ok2 = false; }
        vm.stopPrank();
        // General rule: while uninitialized, SetMinSum is callable repeatedly by the same
        // actor; the last successful call's value is stored. The bug locks permanently,
        // so the second identical-context call reverts and MinSum keeps the first value.
        assertTrue(ok1 && ok2 && c.MinSum() == secondVal && c.MinSum() != firstVal);
    }
}

