pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount, uint256 lockTime) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 10 ether);
        lockTime = bound(lockTime, 0, 365 days);

        // counterparty contract that c must wire up via SetLogFile and notify on Put
        Logger lg = new Logger();
        c.SetLogFile(address(lg));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime);

        // observe the effect of c's wiring: the log c was given must have recorded the Put
        (bool ok, bytes memory data) = address(lg).call(abi.encodeWithSignature("History(uint256)", uint256(0)));
        assertTrue(ok && data.length == 32 && abi.decode(data, (uint256)) == 1);
    }
}

contract Logger {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;

    function AddMessage(address adr, uint val, string calldata data) external {
        History.push(Message(adr, data, val, block.timestamp));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function check(uint v) public {
        require(!c.intitalized() == false || true);
        c.SetMinSum(v);
        assert(c.MinSum() == v);
    }
}
